145:     function push(uint128 id) internal {
146:         AppStorage storage s = LibAppStorage.diamondStorage();
147:         if (s.sys.fert.fertFirst == 0) {
148:             // Queue is empty
149:             s.sys.season.fertilizing = true;
150:             s.sys.fert.fertLast = id;
151:             s.sys.fert.fertFirst = id;
152:         } else if (id <= s.sys.fert.fertFirst) {
153:             // Add to front of queue
154:             setNext(id, s.sys.fert.fertFirst);
155:             s.sys.fert.fertFirst = id;
156:         } else if (id >= s.sys.fert.fertLast) {
157:             // Add to back of queue
158:             setNext(s.sys.fert.fertLast, id);
159:             s.sys.fert.fertLast = id;
160:         } else {
161:             // Add to middle of queue
162:             uint128 prev = s.sys.fert.fertFirst;
163:             uint128 next = getNext(prev);
164:             // Search for proper place in line
165:             while (id > next) {
166:                 prev = next;
167:                 next = getNext(next);
168:             }
169:             setNext(prev, id);
170:             setNext(id, next);
171:         }
172:     }
